INDEX_HTML = '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>침수차 진위확인</title>\n  <style>\n    :root {\n      --primary: #0b6e99;\n      --bg: #f7fbfc;\n      --card: #e7f1f5;\n      --text: #102a43;\n      --border: #c5dce6;\n      --red: #b42318;\n      --green: #027a48;\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      font-family: "Segoe UI", "Apple SD Gothic Neo", sans-serif;\n      background: var(--bg);\n      color: var(--text);\n    }\n    main {\n      max-width: 760px;\n      margin: 0 auto;\n      padding: 32px 20px 64px;\n    }\n    h1 { margin: 0 0 8px; font-size: 1.8rem; }\n    .caption, .hint { color: #486581; font-size: 0.95rem; }\n    form, .result, .notice {\n      background: white;\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 20px;\n      margin-top: 20px;\n    }\n    label { display: block; font-weight: 600; margin: 16px 0 8px; }\n    input[type="text"], input[type="date"], textarea, select {\n      width: 100%;\n      padding: 10px 12px;\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      font: inherit;\n      background: #fff;\n    }\n    textarea { min-height: 96px; }\n    .row { display: flex; gap: 8px; flex-wrap: wrap; }\n    .row > * { flex: 1; min-width: 120px; }\n    .pills { display: flex; flex-wrap: wrap; gap: 8px; }\n    .pills label {\n      margin: 0;\n      font-weight: 500;\n      border: 1px solid var(--border);\n      border-radius: 999px;\n      padding: 8px 12px;\n      background: var(--card);\n      cursor: pointer;\n    }\n    .pills input { display: none; }\n    .pills input:checked + span,\n    .pills label:has(input:checked) {\n      background: var(--primary);\n      color: white;\n      border-color: var(--primary);\n    }\n    .actions { display: flex; gap: 8px; margin-top: 20px; }\n    button, .button {\n      border: 0;\n      border-radius: 8px;\n      padding: 10px 16px;\n      font: inherit;\n      cursor: pointer;\n      text-decoration: none;\n    }\n    button[type="submit"], .primary { background: var(--primary); color: white; }\n    .secondary { background: var(--card); color: var(--text); }\n    .error { color: var(--red); background: #fff1f0; border: 1px solid #ffccc7; border-radius: 8px; padding: 12px; }\n    .ok { color: var(--green); }\n    .metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 16px 0; }\n    .metric { background: var(--card); border-radius: 8px; padding: 12px; }\n    .metric b { display: block; font-size: 1.2rem; }\n    table { width: 100%; border-collapse: collapse; margin-top: 12px; font-size: 0.95rem; }\n    th, td { border-bottom: 1px solid var(--border); text-align: left; padding: 8px; }\n    details { margin-top: 16px; }\n    @media (max-width: 640px) {\n      .metrics { grid-template-columns: 1fr 1fr; }\n    }\n  </style>\n</head>\n<body>\n  <main>\n    <h1>침수차 진위확인</h1>\n    <p class="caption">금융위원회·보험개발원 공공데이터로 자동차보험에 접수된 침수 이력을 조회합니다.</p>\n\n    {% if not key_ready %}\n    <div class="notice error">\n      <p>{{ key_error }}</p>\n      <p>Vercel Environment Variables에 <code>DATA_GO_KR_SERVICE_KEY</code>를 넣어 주세요.</p>\n    </div>\n    {% endif %}\n\n    <form method="post" action="/">\n      <label for="vehicle_text">차량번호</label>\n      <textarea id="vehicle_text" name="vehicle_text" placeholder="한 대: 12가1234&#10;여러 대는 줄바꿈 또는 쉼표로 구분" required>{{ vehicle_text }}</textarea>\n      <p class="hint">최대 {{ batch_limit }}대. 예: 12가1234, 123가1234, 서울12가1234</p>\n\n      <div class="composer">\n        <label>번호판 구성해서 넣기</label>\n        <div class="row">\n          <select id="plate_format">\n            {% for item in plate_formats %}<option>{{ item }}</option>{% endfor %}\n          </select>\n          <select id="plate_region">\n            {% for item in regions %}<option>{{ item }}</option>{% endfor %}\n          </select>\n          <select id="plate_usage">\n            {% for item in letters_by_usage %}<option>{{ item }}</option>{% endfor %}\n          </select>\n        </div>\n        <div class="row" style="margin-top:8px">\n          <input id="plate_prefix" type="text" inputmode="numeric" placeholder="앞번호">\n          <select id="plate_letter"></select>\n          <input id="plate_serial" type="text" inputmode="numeric" maxlength="4" placeholder="1234">\n          <button type="button" class="secondary" id="add_plate">목록에 추가</button>\n        </div>\n      </div>\n\n      <label>사고 종류명</label>\n      <div class="pills">\n        {% for item in kinds %}\n        <label><input type="radio" name="kind_label" value="{{ item }}" {% if kind_label == item %}checked{% endif %}><span>{{ item }}</span></label>\n        {% endfor %}\n      </div>\n      <p class="hint">추천은 전체입니다. 침수분손은 수리비가 차량 가치 이하, 침수전손은 수리 불능 또는 가치 초과입니다.</p>\n\n      <label>조회 기간</label>\n      <div class="pills">\n        {% for item in periods %}\n        <label><input type="radio" name="period_mode" value="{{ item }}" {% if period_mode == item %}checked{% endif %}><span>{{ item }}</span></label>\n        {% endfor %}\n      </div>\n      <p class="hint">기간은 필수가 아닙니다. 비우거나 전체를 고르면 해당 차량의 모든 침수 이력을 조회합니다. 침수는 오래된 사고도 의미가 있어 전체 기간을 추천합니다.</p>\n      <div class="row" id="date_range" style="{% if period_mode != \'직접 지정\' %}display:none{% endif %}">\n        <input type="date" name="start_date" min="{{ min_date }}" max="{{ today }}" value="{{ start_date }}">\n        <input type="date" name="end_date" min="{{ min_date }}" max="{{ today }}" value="{{ end_date }}">\n      </div>\n\n      <div class="actions">\n        <button type="submit" class="primary" {% if not key_ready %}disabled{% endif %}>침수 이력 조회</button>\n        <button type="submit" class="secondary" formaction="/csv" {% if not key_ready %}disabled{% endif %}>CSV로 저장</button>\n      </div>\n    </form>\n\n    {% if error %}\n    <p class="error">{{ error }}</p>\n    {% endif %}\n\n    {% if lookups is not none %}\n    <section class="result">\n      <h2>조회 결과</h2>\n      <p class="caption">{{ lookups|length }}대 · {{ kind_label }} · {{ period_label }}</p>\n      <div class="metrics">\n        <div class="metric">조회 대수<b>{{ lookups|length }}대</b></div>\n        <div class="metric">침수 이력 있음<b>{{ history_count }}대</b></div>\n        <div class="metric">이력 없음<b>{{ empty_count }}대</b></div>\n        <div class="metric">조회 실패<b>{{ fail_count }}대</b></div>\n      </div>\n      {% if history_count %}\n      <p style="color:var(--red)"><strong>침수 이력 있음</strong></p>\n      {% elif fail_count == lookups|length %}\n      <p style="color:var(--red)"><strong>조회 실패</strong></p>\n      {% else %}\n      <p class="ok"><strong>등록된 침수 이력 없음</strong></p>\n      <p class="hint">자동차보험에 접수된 침수 이력이 조회되지 않았습니다. 보험 미처리 사고는 결과에 나타나지 않습니다.</p>\n      {% endif %}\n\n      <table>\n        <thead><tr><th>차량번호</th><th>결과</th><th>건수</th></tr></thead>\n        <tbody>\n          {% for item in lookups %}\n          <tr>\n            <td>{{ item.vehicle_no }}</td>\n            <td>{% if item.error %}조회 실패{% elif item.has_history %}침수 이력 있음{% else %}이력 없음{% endif %}</td>\n            <td>{{ item.records|length }}</td>\n          </tr>\n          {% endfor %}\n        </tbody>\n      </table>\n\n      {% if history_rows %}\n      <table>\n        <thead>\n          <tr>\n            <th>현재 차량번호</th>\n            <th>사고 발생일시</th>\n            <th>사고 종류</th>\n            <th>자료 작성일자</th>\n          </tr>\n        </thead>\n        <tbody>\n          {% for row in history_rows %}\n          <tr>\n            <td>{{ row["현재 차량번호"] }}</td>\n            <td>{{ row["사고 발생일시"] }}</td>\n            <td>{{ row["사고 종류"] }}</td>\n            <td>{{ row["자료 작성일자"] }}</td>\n          </tr>\n          {% endfor %}\n        </tbody>\n      </table>\n      {% endif %}\n    </section>\n    {% endif %}\n\n    <details>\n      <summary>조회 시 유의사항</summary>\n      <ul>\n        <li>결과가 없다고 해서 침수와 무관한 차량이라고 단정할 수 없습니다.</li>\n        <li>보험사에 신고되지 않았거나 자동차보험으로 처리되지 않은 침수는 확인되지 않습니다.</li>\n        <li>같은 번호로 재조회 시 이력이 사라지면 말소 등록 여부를 따로 확인해야 합니다.</li>\n        <li>정밀 확인이 필요하면 차량 진단 전문업체 또는 카히스토리를 함께 이용하세요.</li>\n      </ul>\n    </details>\n  </main>\n  <script>\n    const lettersByUsage = {{ letters_by_usage | tojson }};\n    const prefixLength = {{ prefix_length | tojson }};\n    const formatSel = document.getElementById("plate_format");\n    const regionSel = document.getElementById("plate_region");\n    const usageSel = document.getElementById("plate_usage");\n    const letterSel = document.getElementById("plate_letter");\n    const prefixInput = document.getElementById("plate_prefix");\n    const serialInput = document.getElementById("plate_serial");\n    const vehicleText = document.getElementById("vehicle_text");\n\n    function refreshLetters() {\n      const letters = lettersByUsage[usageSel.value] || [];\n      letterSel.innerHTML = letters.map((ch) => `<option>${ch}</option>`).join("");\n    }\n    function refreshFormat() {\n      const len = prefixLength[formatSel.value] || 3;\n      prefixInput.maxLength = len;\n      regionSel.style.display = formatSel.value === "지역번호판" ? "block" : "none";\n    }\n    function assemble() {\n      const region = formatSel.value === "지역번호판" ? regionSel.value : "";\n      return `${region}${prefixInput.value}${letterSel.value}${serialInput.value}`.replace(/\\s+/g, "");\n    }\n    refreshLetters();\n    refreshFormat();\n    usageSel.addEventListener("change", refreshLetters);\n    formatSel.addEventListener("change", refreshFormat);\n    document.getElementById("add_plate").addEventListener("click", () => {\n      const number = assemble();\n      const current = vehicleText.value.trim();\n      vehicleText.value = current ? `${current}\\n${number}` : number;\n    });\n    document.querySelectorAll("input[name=period_mode]").forEach((el) => {\n      el.addEventListener("change", () => {\n        document.getElementById("date_range").style.display = el.value === "직접 지정" && el.checked ? "flex" : "none";\n      });\n    });\n  </script>\n</body>\n</html>\n'
